type CallCeilF32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedCeilF32 {
    call: CallCeilF32,
    proof: Proof,
}
fn ceil_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::ceilf(x)
}
#[cfg(target_arch = "x86_64")]
fn ceil_f32_ptr_v2(p: Proof, x: f32) -> f32 {
    let Proof::V2(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceilf_v2_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn ceil_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceilf_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn ceil_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceilf_wasm128_t(t, x)
}
fn ceil_f32_select() -> SelectedCeilF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return SelectedCeilF32 {
            call: ceil_f32_ptr_v2,
            proof: Proof::V2(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedCeilF32 {
            call: ceil_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedCeilF32 {
            call: ceil_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedCeilF32 {
        call: ceil_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn ceil_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedCeilF32> = OnceLock::new();
    let c = C.get_or_init(ceil_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn ceil_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return zenmath::simd::scalar::ceilf_v2_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::ceilf_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::ceilf_wasm128_t(t, x);
    }
    zenmath::scalar::reference::ceilf(x)
}
