type CallTruncF32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedTruncF32 {
    call: CallTruncF32,
    proof: Proof,
}
fn trunc_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::floorf(x.abs()).copysign(x)
}
#[cfg(target_arch = "x86_64")]
fn trunc_f32_ptr_v2(p: Proof, x: f32) -> f32 {
    let Proof::V2(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::truncf_v2_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn trunc_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::truncf_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn trunc_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::truncf_wasm128_t(t, x)
}
fn trunc_f32_select() -> SelectedTruncF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return SelectedTruncF32 {
            call: trunc_f32_ptr_v2,
            proof: Proof::V2(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedTruncF32 {
            call: trunc_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedTruncF32 {
            call: trunc_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedTruncF32 {
        call: trunc_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn trunc_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedTruncF32> = OnceLock::new();
    let c = C.get_or_init(trunc_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn trunc_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return zenmath::simd::scalar::truncf_v2_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::truncf_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::truncf_wasm128_t(t, x);
    }
    zenmath::scalar::reference::floorf(x.abs()).copysign(x)
}
