type CallRoundF32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedRoundF32 {
    call: CallRoundF32,
    proof: Proof,
}
fn round_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::roundf(x)
}
#[cfg(target_arch = "x86_64")]
fn round_f32_ptr_v2(p: Proof, x: f32) -> f32 {
    let Proof::V2(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::roundf_v2_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn round_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::roundf_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn round_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::roundf_wasm128_t(t, x)
}
fn round_f32_select() -> SelectedRoundF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return SelectedRoundF32 {
            call: round_f32_ptr_v2,
            proof: Proof::V2(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedRoundF32 {
            call: round_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedRoundF32 {
            call: round_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedRoundF32 {
        call: round_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn round_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedRoundF32> = OnceLock::new();
    let c = C.get_or_init(round_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn round_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return zenmath::simd::scalar::roundf_v2_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::roundf_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::roundf_wasm128_t(t, x);
    }
    zenmath::scalar::reference::roundf(x)
}
