type CallFmaF32 = fn(Proof, f32, f32, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedFmaF32 {
    call: CallFmaF32,
    proof: Proof,
}
fn fma_f32_ptr_scalar(_: Proof, x: f32, y: f32, z: f32) -> f32 {
    zenmath::scalar::reference::fmaf(x, y, z)
}
#[cfg(target_arch = "x86_64")]
fn fma_f32_ptr_v3(p: Proof, x: f32, y: f32, z: f32) -> f32 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fmaf_v3_t(t, x, y, z)
}
#[cfg(target_arch = "aarch64")]
fn fma_f32_ptr_neon(p: Proof, x: f32, y: f32, z: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fmaf_neon_t(t, x, y, z)
}
#[cfg(target_arch = "wasm32")]
fn fma_f32_ptr_wasm128(p: Proof, x: f32, y: f32, z: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fmaf_wasm128_t(t, x, y, z)
}
fn fma_f32_select() -> SelectedFmaF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedFmaF32 {
            call: fma_f32_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedFmaF32 {
            call: fma_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedFmaF32 {
            call: fma_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedFmaF32 {
        call: fma_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn fma_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedFmaF32> = OnceLock::new();
    let c = C.get_or_init(fma_f32_select);
    (c.call)(c.proof, x, y, z)
}
#[inline]
fn fma_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::fmaf_v3_t(t, x, y, z);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::fmaf_neon_t(t, x, y, z);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::fmaf_wasm128_t(t, x, y, z);
    }
    zenmath::scalar::reference::fmaf(x, y, z)
}
