type CallExpF32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedExpF32 {
    call: CallExpF32,
    proof: Proof,
}
fn exp_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::expf(x)
}
#[cfg(target_arch = "x86_64")]
fn exp_f32_ptr_v3(p: Proof, x: f32) -> f32 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::expf_v3_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn exp_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::expf_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn exp_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::expf_wasm128_t(t, x)
}
fn exp_f32_select() -> SelectedExpF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedExpF32 {
            call: exp_f32_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedExpF32 {
            call: exp_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedExpF32 {
            call: exp_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedExpF32 {
        call: exp_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn exp_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedExpF32> = OnceLock::new();
    let c = C.get_or_init(exp_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn exp_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::expf_v3_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::expf_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::expf_wasm128_t(t, x);
    }
    zenmath::scalar::reference::expf(x)
}
