type CallLnF32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedLnF32 {
    call: CallLnF32,
    proof: Proof,
}
fn ln_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::logf(x)
}
#[cfg(target_arch = "x86_64")]
fn ln_f32_ptr_v3(p: Proof, x: f32) -> f32 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::logf_v3_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn ln_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::logf_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn ln_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::logf_wasm128_t(t, x)
}
fn ln_f32_select() -> SelectedLnF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedLnF32 {
            call: ln_f32_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedLnF32 {
            call: ln_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedLnF32 {
            call: ln_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedLnF32 {
        call: ln_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn ln_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedLnF32> = OnceLock::new();
    let c = C.get_or_init(ln_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn ln_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::logf_v3_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::logf_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::logf_wasm128_t(t, x);
    }
    zenmath::scalar::reference::logf(x)
}
