type CallLog2F32 = fn(Proof, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedLog2F32 {
    call: CallLog2F32,
    proof: Proof,
}
fn log2_f32_ptr_scalar(_: Proof, x: f32) -> f32 {
    zenmath::scalar::reference::log2f(x)
}
#[cfg(target_arch = "x86_64")]
fn log2_f32_ptr_v3(p: Proof, x: f32) -> f32 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::log2f_v3_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn log2_f32_ptr_neon(p: Proof, x: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::log2f_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn log2_f32_ptr_wasm128(p: Proof, x: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::log2f_wasm128_t(t, x)
}
fn log2_f32_select() -> SelectedLog2F32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedLog2F32 {
            call: log2_f32_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedLog2F32 {
            call: log2_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedLog2F32 {
            call: log2_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedLog2F32 {
        call: log2_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn log2_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedLog2F32> = OnceLock::new();
    let c = C.get_or_init(log2_f32_select);
    (c.call)(c.proof, x)
}
#[inline]
fn log2_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::log2f_v3_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::log2f_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::log2f_wasm128_t(t, x);
    }
    zenmath::scalar::reference::log2f(x)
}
