type CallPowF32 = fn(Proof, f32, f32) -> f32;
#[derive(Clone, Copy)]
struct SelectedPowF32 {
    call: CallPowF32,
    proof: Proof,
}
fn pow_f32_ptr_scalar(_: Proof, x: f32, y: f32) -> f32 {
    zenmath::scalar::reference::powf(x, y)
}
#[cfg(target_arch = "x86_64")]
fn pow_f32_ptr_v3(p: Proof, x: f32, y: f32) -> f32 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::powf_v3_t(t, x, y)
}
#[cfg(target_arch = "aarch64")]
fn pow_f32_ptr_neon(p: Proof, x: f32, y: f32) -> f32 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::powf_neon_t(t, x, y)
}
#[cfg(target_arch = "wasm32")]
fn pow_f32_ptr_wasm128(p: Proof, x: f32, y: f32) -> f32 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::powf_wasm128_t(t, x, y)
}
fn pow_f32_select() -> SelectedPowF32 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedPowF32 {
            call: pow_f32_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedPowF32 {
            call: pow_f32_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedPowF32 {
            call: pow_f32_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedPowF32 {
        call: pow_f32_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn pow_f32_cached(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    static C: OnceLock<SelectedPowF32> = OnceLock::new();
    let c = C.get_or_init(pow_f32_select);
    (c.call)(c.proof, x, y)
}
#[inline]
fn pow_f32_branch(x: f32, y: f32, z: f32) -> f32 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::powf_v3_t(t, x, y);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::powf_neon_t(t, x, y);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::powf_wasm128_t(t, x, y);
    }
    zenmath::scalar::reference::powf(x, y)
}
