pub fn cases32(op: &str, feedback: bool) -> Vec<Case<f32>> {
    match (op, feedback) {
        ("sqrt", false) => sqrt_f32_stream_cases(),
        ("sqrt", true) => sqrt_f32_feedback_cases(),
        ("floor", false) => floor_f32_stream_cases(),
        ("floor", true) => floor_f32_feedback_cases(),
        ("ceil", false) => ceil_f32_stream_cases(),
        ("ceil", true) => ceil_f32_feedback_cases(),
        ("trunc", false) => trunc_f32_stream_cases(),
        ("trunc", true) => trunc_f32_feedback_cases(),
        ("roundeven", false) => roundeven_f32_stream_cases(),
        ("roundeven", true) => roundeven_f32_feedback_cases(),
        ("round", false) => round_f32_stream_cases(),
        ("round", true) => round_f32_feedback_cases(),
        ("fma", false) => fma_f32_stream_cases(),
        ("fma", true) => fma_f32_feedback_cases(),
        ("exp", false) => exp_f32_stream_cases(),
        ("exp", true) => exp_f32_feedback_cases(),
        ("ln", false) => ln_f32_stream_cases(),
        ("ln", true) => ln_f32_feedback_cases(),
        ("log2", false) => log2_f32_stream_cases(),
        ("log2", true) => log2_f32_feedback_cases(),
        ("pow", false) => pow_f32_stream_cases(),
        ("pow", true) => pow_f32_feedback_cases(),
        ("pow_rescue", false) => pow_rescue_f32_stream_cases(),
        _ => panic!("unsupported workload"),
    }
}
