type CallCeilF64 = fn(Proof, f64) -> f64;
#[derive(Clone, Copy)]
struct SelectedCeilF64 {
    call: CallCeilF64,
    proof: Proof,
}
fn ceil_f64_ptr_scalar(_: Proof, x: f64) -> f64 {
    zenmath::scalar::reference::ceil(x)
}
#[cfg(target_arch = "x86_64")]
fn ceil_f64_ptr_v2(p: Proof, x: f64) -> f64 {
    let Proof::V2(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceil_v2_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn ceil_f64_ptr_neon(p: Proof, x: f64) -> f64 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceil_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn ceil_f64_ptr_wasm128(p: Proof, x: f64) -> f64 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::ceil_wasm128_t(t, x)
}
fn ceil_f64_select() -> SelectedCeilF64 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return SelectedCeilF64 {
            call: ceil_f64_ptr_v2,
            proof: Proof::V2(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedCeilF64 {
            call: ceil_f64_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedCeilF64 {
            call: ceil_f64_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedCeilF64 {
        call: ceil_f64_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn ceil_f64_cached(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    static C: OnceLock<SelectedCeilF64> = OnceLock::new();
    let c = C.get_or_init(ceil_f64_select);
    (c.call)(c.proof, x)
}
#[inline]
fn ceil_f64_branch(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return zenmath::simd::scalar::ceil_v2_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::ceil_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::ceil_wasm128_t(t, x);
    }
    zenmath::scalar::reference::ceil(x)
}
