type CallTruncF64 = fn(Proof, f64) -> f64;
#[derive(Clone, Copy)]
struct SelectedTruncF64 {
    call: CallTruncF64,
    proof: Proof,
}
fn trunc_f64_ptr_scalar(_: Proof, x: f64) -> f64 {
    zenmath::scalar::reference::floor(x.abs()).copysign(x)
}
#[cfg(target_arch = "x86_64")]
fn trunc_f64_ptr_v2(p: Proof, x: f64) -> f64 {
    let Proof::V2(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::trunc_v2_t(t, x)
}
#[cfg(target_arch = "aarch64")]
fn trunc_f64_ptr_neon(p: Proof, x: f64) -> f64 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::trunc_neon_t(t, x)
}
#[cfg(target_arch = "wasm32")]
fn trunc_f64_ptr_wasm128(p: Proof, x: f64) -> f64 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::trunc_wasm128_t(t, x)
}
fn trunc_f64_select() -> SelectedTruncF64 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return SelectedTruncF64 {
            call: trunc_f64_ptr_v2,
            proof: Proof::V2(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedTruncF64 {
            call: trunc_f64_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedTruncF64 {
            call: trunc_f64_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedTruncF64 {
        call: trunc_f64_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn trunc_f64_cached(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    static C: OnceLock<SelectedTruncF64> = OnceLock::new();
    let c = C.get_or_init(trunc_f64_select);
    (c.call)(c.proof, x)
}
#[inline]
fn trunc_f64_branch(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V2Token::summon() {
        return zenmath::simd::scalar::trunc_v2_t(t, x);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::trunc_neon_t(t, x);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::trunc_wasm128_t(t, x);
    }
    zenmath::scalar::reference::floor(x.abs()).copysign(x)
}
