type CallFmaF64 = fn(Proof, f64, f64, f64) -> f64;
#[derive(Clone, Copy)]
struct SelectedFmaF64 {
    call: CallFmaF64,
    proof: Proof,
}
fn fma_f64_ptr_scalar(_: Proof, x: f64, y: f64, z: f64) -> f64 {
    zenmath::scalar::reference::fma(x, y, z)
}
#[cfg(target_arch = "x86_64")]
fn fma_f64_ptr_v3(p: Proof, x: f64, y: f64, z: f64) -> f64 {
    let Proof::V3(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fma_v3_t(t, x, y, z)
}
#[cfg(target_arch = "aarch64")]
fn fma_f64_ptr_neon(p: Proof, x: f64, y: f64, z: f64) -> f64 {
    let Proof::Neon(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fma_neon_t(t, x, y, z)
}
#[cfg(target_arch = "wasm32")]
fn fma_f64_ptr_wasm128(p: Proof, x: f64, y: f64, z: f64) -> f64 {
    let Proof::Wasm(t) = p else {
        unreachable!("selector/proof mismatch")
    };
    zenmath::simd::scalar::fma_wasm128_t(t, x, y, z)
}
fn fma_f64_select() -> SelectedFmaF64 {
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return SelectedFmaF64 {
            call: fma_f64_ptr_v3,
            proof: Proof::V3(t),
        };
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return SelectedFmaF64 {
            call: fma_f64_ptr_neon,
            proof: Proof::Neon(t),
        };
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return SelectedFmaF64 {
            call: fma_f64_ptr_wasm128,
            proof: Proof::Wasm(t),
        };
    }
    SelectedFmaF64 {
        call: fma_f64_ptr_scalar,
        proof: Proof::Scalar,
    }
}
#[inline]
fn fma_f64_cached(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    static C: OnceLock<SelectedFmaF64> = OnceLock::new();
    let c = C.get_or_init(fma_f64_select);
    (c.call)(c.proof, x, y, z)
}
#[inline]
fn fma_f64_branch(x: f64, y: f64, z: f64) -> f64 {
    let _ = (y, z);
    #[cfg(target_arch = "x86_64")]
    if let Some(t) = X64V3Token::summon() {
        return zenmath::simd::scalar::fma_v3_t(t, x, y, z);
    }
    #[cfg(target_arch = "aarch64")]
    if let Some(t) = NeonToken::summon() {
        return zenmath::simd::scalar::fma_neon_t(t, x, y, z);
    }
    #[cfg(target_arch = "wasm32")]
    if let Some(t) = Wasm128Token::summon() {
        return zenmath::simd::scalar::fma_wasm128_t(t, x, y, z);
    }
    zenmath::scalar::reference::fma(x, y, z)
}
