pub fn cases64(op: &str, feedback: bool) -> Vec<Case<f64>> {
    match (op, feedback) {
        ("sqrt", false) => sqrt_f64_stream_cases(),
        ("sqrt", true) => sqrt_f64_feedback_cases(),
        ("floor", false) => floor_f64_stream_cases(),
        ("floor", true) => floor_f64_feedback_cases(),
        ("ceil", false) => ceil_f64_stream_cases(),
        ("ceil", true) => ceil_f64_feedback_cases(),
        ("trunc", false) => trunc_f64_stream_cases(),
        ("trunc", true) => trunc_f64_feedback_cases(),
        ("roundeven", false) => roundeven_f64_stream_cases(),
        ("roundeven", true) => roundeven_f64_feedback_cases(),
        ("round", false) => round_f64_stream_cases(),
        ("round", true) => round_f64_feedback_cases(),
        ("fma", false) => fma_f64_stream_cases(),
        ("fma", true) => fma_f64_feedback_cases(),
        _ => panic!("unsupported workload"),
    }
}
